use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,io::{Read,Write},path::Path,process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/rns-screen";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-28-rns-screen";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn main(){let r=Path::new(R);let d=Path::new(D);if std::env::args().nth(1).as_deref()==Some("verify"){let v=read(d.join("artifact-index.json"));let mut text=String::new();for(f,h)in v.as_object().unwrap(){assert!(!f.contains('\n')&&!f.contains('\\'));text.push_str(&format!("{}  artifacts/{f}\n",h.as_str().unwrap()));}let mut child=Command::new("sha256sum").args(["--check","--strict","-"]).current_dir(d).stdin(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(text.as_bytes()).unwrap();assert!(child.wait().unwrap().success());println!("Independent GNU check: {}artifact hashes",v.as_object().unwrap().len());return}
 for(p,h)in read(r.join("pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let a=read(r.join("analysis.json"));assert_eq!(a["native_trial_justified"],false);assert_eq!(a["proof_ledger_unchanged"],12524);assert_eq!(a["fields"].as_array().unwrap().len(),2);let count:u64=a["fields"].as_array().unwrap().iter().map(|f|f["total_reductions"].as_u64().unwrap()).sum();assert_eq!(count,34400);
 fs::write(r.join("closeout.json"),serde_json::to_vec_pretty(&json!({"status":"complete","exact_reductions":34400,"new_tests":5,"successful_tests_repeated":false,"SDK_requests":0,"new_exports":0,"proof_ledger_unchanged":12524,"adopted":false,"goal_achieved":false,"owned_jobs":[],"owned_cloud_resources":[]})).unwrap()).unwrap();fs::create_dir_all(d.join("artifacts")).unwrap();let mut index=BTreeMap::new();for e in fs::read_dir(r).unwrap(){let e=e.unwrap();let p=e.path();if !e.file_type().unwrap().is_file(){continue}let name=e.file_name().to_string_lossy().to_string();if name=="research-notes.md"||!(["rs","json","log","md","txt","sha256"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or(""))){continue}let dest=d.join("artifacts").join(&name);fs::copy(&p,&dest).unwrap();assert_eq!(hash(&p),hash(&dest));index.insert(name,hash(&dest));}fs::write(d.join("artifact-index.json"),serde_json::to_vec_pretty(&json!(index)).unwrap()).unwrap();println!("Closed RNS arithmetic/conversion screen;34400reductions;{}artifact hashes;ledger12524 unchanged",index.len());
}
